// Python's json.loads(bytes) and str()/repr() of what it returns, for views
// that do `json.loads(request.body)` and store values through Django model
// fields (which call str() on non-strings). JSON.parse can't be used: it
// forgets whether a number was written as an int (5) or a float (5.0), loses
// precision on big ints, and rejects NaN/Infinity, which Python accepts.
// Golden-tested against Python 3.12 (tests/fixtures/doctor_info_golden.json,
// generated by parity-tools/golden/doctor_info.py).
//
// Value mapping: JSON object → Map (keeps Python's key order, duplicate keys:
// last value wins in the first key's position), array → Array, string →
// string, int → BigInt, float → number, true/false → boolean, null → null.

/** A Python exception; `pyType` is the class name Django would have raised (every one is a 500). */
export class PythonError extends Error {
  constructor(pyType, message) {
    super(`${pyType}: ${message}`);
    this.pyType = pyType;
  }
}

// ─── bytes → str: json.detect_encoding + bytes.decode(enc, 'surrogatepass') ───

function detectEncoding(b) {
  const starts = (...bytes) => bytes.every((v, i) => b[i] === v);
  if (starts(0x00, 0x00, 0xfe, 0xff) || starts(0xff, 0xfe, 0x00, 0x00)) return 'utf-32';
  if (starts(0xfe, 0xff) || starts(0xff, 0xfe)) return 'utf-16';
  if (starts(0xef, 0xbb, 0xbf)) return 'utf-8-sig';
  if (b.length >= 4) {
    if (!b[0]) return b[1] ? 'utf-16-be' : 'utf-32-be';
    if (!b[1]) return b[2] || b[3] ? 'utf-16-le' : 'utf-32-le';
  } else if (b.length === 2) {
    if (!b[0]) return 'utf-16-be';
    if (!b[1]) return 'utf-16-le';
  }
  return 'utf-8';
}

function decodeUtf32(b, littleEndian) {
  if (b.length % 4 !== 0) throw new PythonError('UnicodeDecodeError', 'truncated data');
  const view = new DataView(b.buffer, b.byteOffset, b.byteLength);
  let out = '';
  for (let i = 0; i < b.length; i += 4) {
    const cp = view.getUint32(i, littleEndian);
    if (cp > 0x10ffff) throw new PythonError('UnicodeDecodeError', 'code point not in range(0x110000)');
    out += cp >= 0xd800 && cp <= 0xdfff ? String.fromCharCode(cp) : String.fromCodePoint(cp);
  }
  return out;
}

function decode(b) {
  const strict = (label, bytes) => {
    try {
      return new TextDecoder(label, { fatal: true, ignoreBOM: true }).decode(bytes);
    } catch {
      // Python's 'surrogatepass' would accept encoded lone surrogates here.
      throw new PythonError('UnicodeDecodeError', `invalid ${label} data`);
    }
  };
  switch (detectEncoding(b)) {
    case 'utf-32':
      return decodeUtf32(b.subarray(4), b[0] === 0xff);
    case 'utf-32-be':
      return decodeUtf32(b, false);
    case 'utf-32-le':
      return decodeUtf32(b, true);
    case 'utf-16':
      return strict(b[0] === 0xff ? 'utf-16le' : 'utf-16be', b.subarray(2));
    case 'utf-16-be':
      return strict('utf-16be', b);
    case 'utf-16-le':
      return strict('utf-16le', b);
    case 'utf-8-sig':
      return strict('utf-8', b.subarray(3));
    default:
      return strict('utf-8', b);
  }
}

// ─── str → value: the C scanner behind json.loads (Lib/json/decoder.py, Modules/_json.c) ───

// CPython refuses int() of more than 4300 digits (sys.int_info.str_digits_check_threshold).
const INT_MAX_STR_DIGITS = 4300;
const NUMBER = /-?(?:0|[1-9][0-9]*)(\.[0-9]+)?([eE][-+]?[0-9]+)?/y;
const WS = /[ \t\n\r]*/y;
const fail = (message) => {
  throw new PythonError('JSONDecodeError', message);
};

function parse(s) {
  let i = 0;
  const skipWs = () => {
    WS.lastIndex = i;
    WS.exec(s);
    i = WS.lastIndex;
  };

  function string() {
    // s[i] is the opening quote.
    let out = '';
    i += 1;
    for (;;) {
      if (i >= s.length) fail('Unterminated string');
      const ch = s[i];
      if (ch === '"') {
        i += 1;
        return out;
      }
      if (ch.charCodeAt(0) <= 0x1f) fail('Invalid control character');
      if (ch !== '\\') {
        out += ch;
        i += 1;
        continue;
      }
      const esc = s[i + 1];
      const simple = { '"': '"', '\\': '\\', '/': '/', b: '\b', f: '\f', n: '\n', r: '\r', t: '\t' }[esc];
      if (simple !== undefined) {
        out += simple;
        i += 2;
        continue;
      }
      if (esc !== 'u') fail('Invalid \\escape');
      const unit = (at) => {
        const hex = s.slice(at, at + 4);
        if (!/^[0-9a-fA-F]{4}$/.test(hex)) fail('Invalid \\uXXXX escape');
        return parseInt(hex, 16);
      };
      let code = unit(i + 2);
      i += 6;
      // A high surrogate followed by an escaped low surrogate is one character;
      // anything else stays a lone surrogate, as in Python.
      if (code >= 0xd800 && code <= 0xdbff && s[i] === '\\' && s[i + 1] === 'u') {
        const low = unit(i + 2);
        if (low >= 0xdc00 && low <= 0xdfff) {
          code = 0x10000 + ((code - 0xd800) << 10) + (low - 0xdc00);
          i += 6;
        }
      }
      out += code > 0xffff ? String.fromCodePoint(code) : String.fromCharCode(code);
    }
  }

  function number() {
    NUMBER.lastIndex = i;
    const m = NUMBER.exec(s);
    if (!m) fail('Expecting value');
    i = NUMBER.lastIndex;
    if (m[1] !== undefined || m[2] !== undefined) return Number(m[0]); // float(); '1e400' → inf like Python
    const digits = m[0].replace('-', '').length;
    if (digits > INT_MAX_STR_DIGITS)
      throw new PythonError('ValueError', 'Exceeds the limit for integer string conversion');
    return BigInt(m[0]);
  }

  function value() {
    const ch = s[i];
    if (ch === '"') return string();
    if (ch === '{') return object();
    if (ch === '[') return array();
    for (const [word, v] of [
      ['null', null],
      ['true', true],
      ['false', false],
      ['NaN', NaN],
      ['Infinity', Infinity],
      ['-Infinity', -Infinity],
    ]) {
      if (s.startsWith(word, i)) {
        i += word.length;
        return v;
      }
    }
    if (ch === '-' || (ch >= '0' && ch <= '9')) return number();
    return fail('Expecting value');
  }

  function object() {
    const map = new Map();
    i += 1;
    skipWs();
    if (s[i] === '}') {
      i += 1;
      return map;
    }
    for (;;) {
      if (s[i] !== '"') fail('Expecting property name enclosed in double quotes');
      const key = string();
      skipWs();
      if (s[i] !== ':') fail("Expecting ':' delimiter");
      i += 1;
      skipWs();
      map.set(key, value());
      skipWs();
      if (s[i] === '}') {
        i += 1;
        return map;
      }
      if (s[i] !== ',') fail("Expecting ',' delimiter");
      i += 1;
      skipWs();
    }
  }

  function array() {
    const list = [];
    i += 1;
    skipWs();
    if (s[i] === ']') {
      i += 1;
      return list;
    }
    for (;;) {
      list.push(value());
      skipWs();
      if (s[i] === ']') {
        i += 1;
        return list;
      }
      if (s[i] !== ',') fail("Expecting ',' delimiter");
      i += 1;
      skipWs();
    }
  }

  skipWs();
  const result = value();
  skipWs();
  if (i !== s.length) fail('Extra data');
  return result;
}

/**
 * Python `json.loads(raw_bytes)`.
 *
 * @param {Buffer | Uint8Array} bytes the raw request body
 * @returns {unknown} see the value mapping at the top of the file
 * @throws {PythonError} JSONDecodeError, UnicodeDecodeError or ValueError
 */
export function pyJsonLoads(bytes) {
  return parse(decode(bytes));
}
